import{_ as e,o as a,c as l,b6 as d}from"./chunks/framework.BUXTSoD9.js";const x=JSON.parse('{"title":"مقدمة المشروع","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/guide/introduction.md","filePath":"ar-sa/guide/introduction.md"}'),i={name:"ar-sa/guide/introduction.md"};function n(r,t,s,g,f,y){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="مقدمة-المشروع" tabindex="-1">مقدمة المشروع <a class="header-anchor" href="#مقدمة-المشروع" aria-label="Permalink to “مقدمة المشروع”">​</a></h1><p>في عام 2025، اعتبره الكثيرون عام انطلاق برمجة الذكاء الاصطناعي. بدأ المزيد والمزيد من الأشخاص يستخدمون الذكاء الاصطناعي لكتابة التعليمات البرمجية، لكن ما ينتجونه غالبًا ما يبقى عند مستوى الألعاب - لا يعرفون كيفية تنظيم عملية التطوير باستخدام Vibe Coding، ولا يعرفون الأدوات التي يجب اختيارها، ولا يفهمون بوضوح الخطوات الحاسمة المفقودة بين النموذج الأولي والإطلاق.</p><p>نعتمد مسارًا عمليًا تدريجيًا من <strong>ثلاث مراحل</strong>: مرحلة المبتدئين للبدء السريع في برمجة الذكاء الاصطناعي من خلال الألعاب الصغيرة، والمرحلة الأولى لإتقان أسلوب العمل في Vibe Coding وإكمال نموذج أولي لتطبيق ويب، والمرحلة الثانية لتعلم التطوير الشامل والنشر، والمرحلة الثالثة لبناء تطبيقات معقدة عبر منصات متعددة.</p><p>تتضمن كل مرحلة مشاريع عملية كاملة، مما يتيح لك الانتقال من الألعاب إلى المنتجات الحقيقية في تحديات واقعية، وفي النهاية تمتلك <strong>القدرة على تحويل أي فكرة إلى تطبيق قابل للاستخدام</strong>.</p><p>نحن نؤمن بأن إتقان Vibe Coding مع التدريب المنهجي سيجعلك شخصيًا مطورًا شاملاً يجمع بين <strong>تطوير الواجهة الأمامية والخلفية، وتكامل قدرات الذكاء الاصطناعي، وتصميم المنتجات</strong>.</p><p>يستهدف هذا المشروع بشكل أساسي ثلاث فئات من المتعلمين:</p><ul><li><strong>المبتدئون (الأشخاص العاديون / الجانب المتعلق بالمنتجات والعمليات)</strong>: مساعدة الأشخاص ذوي الخلفيات غير التقنية والمتعلمين المبتدئين على فهم المفاهيم الرئيسية وإكمال أول أداة صغيرة بالذكاء الاصطناعي أو نموذج أولي للمنتج.</li><li><strong>المطورون المتوسطون والمبتدئون (الطلاب والمطورون ذوو الأساسيات)</strong>: إتقان vibe coding وتطوير تطبيقات الذكاء الاصطناعي الأصلية بشكل منهجي.</li><li><strong>المطورون المتقدمون (الشركات والشركات الناشئة، والمطورون المستقلون والمفتوحو المصدر)</strong>: دعم الفرق والأفراد للبناء السريع والتحقق من التكرار لتطبيقات الذكاء الاصطناعي الأصلية.</li></ul><h2 id="دليل-المحتوى" tabindex="-1">دليل المحتوى <a class="header-anchor" href="#دليل-المحتوى" aria-label="Permalink to “دليل المحتوى”">​</a></h2><h3 id="الملخص-العام" tabindex="-1">الملخص العام <a class="header-anchor" href="#الملخص-العام" aria-label="Permalink to “الملخص العام”">​</a></h3><p><a href="/easy-vibe-ja-learning-map/ar-sa/appendix/8-artificial-intelligence/ai-capability-dictionary.html">قاموس قدرات الذكاء الاصطناعي: المفاهيم الأساسية والمصطلحات وسيناريوهات الذكاء الاصطناعي الشائعة</a></p><h3 id="المرحلة-الصفرية-روضة-الأطفال" tabindex="-1">المرحلة الصفرية: روضة الأطفال <a class="header-anchor" href="#المرحلة-الصفرية-روضة-الأطفال" aria-label="Permalink to “المرحلة الصفرية: روضة الأطفال”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">الفصل</th><th style="text-align:left;">المحتوى الرئيسي</th><th style="text-align:left;">الحالة</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/learning-map/">دليل المبتدئين: خريطة التعلم</a></td><td style="text-align:left;">نظرة عامة على مسار التعلم الكامل</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/ai-capabilities-through-games/">دليل المبتدئين: في عصر الذكاء الاصطناعي، التحدث يعني البرمجة</a></td><td style="text-align:left;">تجربة قدرات برمجة الذكاء الاصطناعي من خلال أمثلة مثل لعبة الثعبان</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="المرحلة-الأولى-مدير-منتجات-الذكاء-الاصطناعي" tabindex="-1">المرحلة الأولى: مدير منتجات الذكاء الاصطناعي <a class="header-anchor" href="#المرحلة-الأولى-مدير-منتجات-الذكاء-الاصطناعي" aria-label="Permalink to “المرحلة الأولى: مدير منتجات الذكاء الاصطناعي”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">الفصل</th><th style="text-align:left;">المحتوى الرئيسي</th><th style="text-align:left;">الحالة</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/introduction-to-ai-ide/">المستوى الثاني: التعرف على أدوات AI IDE</a></td><td style="text-align:left;">تعلم استخدام IDE، وإتقان هيكل الواجهة وأساليب الإدخال الفعالة</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/building-prototype/">المستوى الثالث: بناء نموذج أولي عمليًا</a></td><td style="text-align:left;">دورة كاملة من تحليل المنتج إلى تفكيك المتطلبات وتنفيذ نموذج أولي متعدد الصفحات</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/integrating-ai-capabilities/">المستوى الرابع: إضافة قدرات الذكاء الاصطناعي إلى النموذج الأولي</a></td><td style="text-align:left;">فهم وإكمال تكامل API لقدرات الذكاء الاصطناعي الشائعة (نص، صورة، فيديو)</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/complete-project-practice/">المستوى الخامس: مشروع عملي كامل</a></td><td style="text-align:left;">محاكاة سيناريوهات واقعية، وقبول ملاحظات المستخدمين للتكرار وإكمال عرض المشروع (يتضمن مشروعًا نهائيًا)</td><td style="text-align:left;">✅</td></tr></tbody></table><h4 id="الملاحق" tabindex="-1">الملاحق <a class="header-anchor" href="#الملاحق" aria-label="Permalink to “الملاحق”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">الفصل</th><th style="text-align:left;">المحتوى الرئيسي</th><th style="text-align:left;">الحالة</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/appendix-a-product-thinking/">الملحق أ: التفكير في المنتجات</a></td><td style="text-align:left;">إطار عمل التفكير في المنتجات من تقييم الأفكار إلى تفكيك المتطلبات و MVP</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/appendix-b-common-errors/">الملحق ب: الأخطاء الشائعة والحلول</a></td><td style="text-align:left;">الأخطاء الشائعة في vibe coding وطرق استكشاف الأخطاء وإصلاحها</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/appendix-idea-sources/">الملحق: من أين تأتي الأفكار</a></td><td style="text-align:left;">استخراج اتجاهات محددة من التطبيقات المرجعية والاتجاهات وقوائم المستثمرين</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/appendix-double-diamond/">الملحق: نموذج الماس المزدوج</a></td><td style="text-align:left;">فهم الإيقاع الكامل لتعريف المشكلة أولاً، ثم تطوير تصميم الحل</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/appendix-jobs-to-be-done/">الملحق: Jobs to Be Done</a></td><td style="text-align:left;">استخدام طريقة JTBD لفهم ما يريد المستخدمون حقًا إنجازه</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-1/appendix-mom-test/">الملحق: طريقة مقابلة The Mom Test</a></td><td style="text-align:left;">طريقة بحث للتحقق من المتطلبات من خلال مقابلات المستخدمين</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="المرحلة-الثانية-مهندسو-التطوير-المتوسطون-والمبتدئون" tabindex="-1">المرحلة الثانية: مهندسو التطوير المتوسطون والمبتدئون <a class="header-anchor" href="#المرحلة-الثانية-مهندسو-التطوير-المتوسطون-والمبتدئون" aria-label="Permalink to “المرحلة الثانية: مهندسو التطوير المتوسطون والمبتدئون”">​</a></h3><h4 id="قسم-الواجهة-الأمامية" tabindex="-1">قسم الواجهة الأمامية <a class="header-anchor" href="#قسم-الواجهة-الأمامية" aria-label="Permalink to “قسم الواجهة الأمامية”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">الفصل</th><th style="text-align:left;">المحتوى الرئيسي</th><th style="text-align:left;">الحالة</th></tr></thead><tbody><tr><td style="text-align:left;">استخدام lovart لإنتاج المواد</td><td style="text-align:left;">تعلم استخدام lovart لإنشاء المواد المرئية مثل الشخصيات والمشاهد دفعة واحدة، مما يوفر أساسًا للمواد لتصميم UI وتطوير الواجهة الأمامية</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">مقدمة في Figma و MasterGo</td><td style="text-align:left;">استخدام أدوات التصميم لتنظيم هيكل المعلومات وبنية الصفحات، ووضع الأساس لتنفيذ الواجهة الأمامية</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">بناء أول تطبيق حديث - تصميم UI</td><td style="text-align:left;">إكمال واجهة مبنية على المكونات بناءً على تصميمات، وتحقيق أول رابط من التصميم إلى التعليمات البرمجية</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">تصميم الصفحات والأزرار وفقًا لمعايير تصميم UI</td><td style="text-align:left;">تعلم تنظيم هيكل الصفحة والتسلسل الهرمي للأزرار باستخدام معايير التصميم السائدة، وإنشاء مخططات تصميم بمساعدة الذكاء الاصطناعي</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-2/frontend/hogwarts-portraits/">بناء لوحة هوغوورتس معًا</a></td><td style="text-align:left;">بناء تطبيق واجهة أمامية مع قدرات الذكاء الاصطناعي من الصفر، وربط التصميم والتطوير</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="قسم-تطوير-الواجهة-الخلفية" tabindex="-1">قسم تطوير الواجهة الخلفية <a class="header-anchor" href="#قسم-تطوير-الواجهة-الخلفية" aria-label="Permalink to “قسم تطوير الواجهة الخلفية”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">الفصل</th><th style="text-align:left;">المحتوى الرئيسي</th><th style="text-align:left;">الحالة</th></tr></thead><tbody><tr><td style="text-align:left;">ما هو API</td><td style="text-align:left;">فهم واجهات HTTP ونموذج الطلب والاستجابة، التحضير لتكامل الواجهة الخلفية والاختبار المشترك</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-2/backend/database-supabase/">من قاعدة البيانات إلى Supabase</a></td><td style="text-align:left;">تنفيذ قاعدة البيانات وAPI على Supabase، وربط نموذج البيانات بصفحات الواجهة الأمامية</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">مساعدة النموذج الكبير في كتابة كود الواجهة ووثائق الواجهة</td><td style="text-align:left;">استخدام النموذج الكبير للمساعدة في إنشاء وثائق واجهة وقاعدة بيانات وكود، وتنفيذ واجهة خلفية قابلة للقراءة والاختبار</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">سير عمل Git والنشر على Zeabur</td><td style="text-align:left;">إدارة الكود في سير عمل Git، ونشر التطبيق على Zeabur للإطلاق</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">أدوات تطوير CLI الحديثة</td><td style="text-align:left;">استخدام أدوات برمجة CLI المعتمدة على الذكاء الاصطناعي لتسريع التطوير والتصحيح، وتشكيل سير عمل هندسي شخصي</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">كيفية تكامل stripe وأنظمة الدفع الأخرى</td><td style="text-align:left;">تكامل نظام الدفع، وإكمال رابط الدفع وعملية التسوية الأساسية</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">بناء أول تطبيق حديث - تطبيق شامل</td><td style="text-align:left;">دمج الواجهة الأمامية والخلفية ووحدة الدفع، وإكمال تطبيق ويب شامل قابل للإطلاق</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">مكتبة مكونات الواجهة الأمامية الحديثة + Trae عمليًا</td><td style="text-align:left;">استخدام مكتبة مكونات الواجهة الأمامية الحديثة و Trae، وإكمال منتج بشكل مستقل يدعم التسجيل وتسجيل الدخول والدفع</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="ملخص-قدرات-الذكاء-الاصطناعي" tabindex="-1">ملخص قدرات الذكاء الاصطناعي <a class="header-anchor" href="#ملخص-قدرات-الذكاء-الاصطناعي" aria-label="Permalink to “ملخص قدرات الذكاء الاصطناعي”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">الفصل</th><th style="text-align:left;">المحتوى الرئيسي</th><th style="text-align:left;">الحالة</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/ar-sa/stage-2/ai-capabilities/dify-knowledge-base/">مقدمة في Dify وتكامل قاعدة المعرفة</a></td><td style="text-align:left;">بناء منتجات من فئة الأدوات باستخدام Dify Workflow وRAG الأساسي، كنموذج أولي لترقية التطبيقات اللاحقة</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">تعلم الاستعلام عن قاموس الذكاء الاصطناعي وتكامل API متعدد الوسائط</td><td style="text-align:left;">تعلم كيفية العثور على النماذج وAPI المناسبين، ودمج قدرات الوسائط المتعددة مثل النص والصور في المنتجات</td><td style="text-align:left;">🚧</td></tr></tbody></table><h3 id="المرحلة-الثالثة-مهندسو-التطوير-المتقدمون" tabindex="-1">المرحلة الثالثة: مهندسو التطوير المتقدمون <a class="header-anchor" href="#المرحلة-الثالثة-مهندسو-التطوير-المتقدمون" aria-label="Permalink to “المرحلة الثالثة: مهندسو التطوير المتقدمون”">​</a></h3>',24)])])}const o=e(i,[["render",n]]);export{x as __pageData,o as default};
